CREATE OR ALTER PROCEDURE [dbo].[uspComplaintHistory_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ComplaintId UNIQUEIDENTIFIER = NULL
	, @EventType NVARCHAR(MAX) = NULL
	, @OldStatus NVARCHAR(MAX) = NULL
	, @NewStatus NVARCHAR(MAX) = NULL
	, @ActorId UNIQUEIDENTIFIER = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ComplaintId]
			, t.[EventType]
			, t.[OldStatus]
			, t.[NewStatus]
			, t.[Comment]
			, t.[EventAt]
			, t.[ActorId]
			, t.[CreatedDate]
		FROM [dbo].[ComplaintHistory] AS t
		
		WHERE 1 = 1
			AND (@ComplaintId IS NULL OR t.[ComplaintId] = @ComplaintId)
			AND (ISNULL(@EventType, '') = '' OR t.[EventType] = @EventType)
			AND (ISNULL(@OldStatus, '') = '' OR t.[OldStatus] = @OldStatus)
			AND (ISNULL(@NewStatus, '') = '' OR t.[NewStatus] = @NewStatus)
			AND (@ActorId IS NULL OR t.[ActorId] = @ActorId)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'complaintId' THEN r.[ComplaintId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'complaintId' THEN r.[ComplaintId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'eventType' THEN r.[EventType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'eventType' THEN r.[EventType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'oldStatus' THEN r.[OldStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'oldStatus' THEN r.[OldStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'newStatus' THEN r.[NewStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'newStatus' THEN r.[NewStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'comment' THEN r.[Comment] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'comment' THEN r.[Comment] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'eventAt' THEN r.[EventAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'eventAt' THEN r.[EventAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'actorId' THEN r.[ActorId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'actorId' THEN r.[ActorId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
